// Target and Energy assumptions
options swap_delay=12 iteration=1000;
target lvl=100 resist=0.1 radius=2 pos=0,2.4 hp=999999999; # standard ST target
energy every interval=480,720 amount=1; # standard Energy drops


fn try_zibai_burst() {
  if .zibai.burst.ready {
    zibai attack, burst;
  }
}
let skill_time = -1000000;

// Rotation assumptions
active linnea;
for let i=0; i<6; i=i+1 {
  linnea skill;
  
  columbina skill;
  if .columbina.burst.ready {
    columbina burst;
  } else {
    columbina attack:2;
  }
  illuga skill, burst;
  zibai skill;
  if .zibai.cons >= 1 {
    zibai skill;
  }
  try_zibai_burst();
  zibai attack:4, skill;
  try_zibai_burst();
  zibai attack:4, skill;
  try_zibai_burst();
  zibai attack:4, skill;
  try_zibai_burst();
  zibai attack:4;
  if i < 5 && !.columbina.burst.ready && .zibai.cons == 0 {
    zibai attack:2;
  }
  if !i && .zibai.cons > 0 {
    zibai attack;
  }
  zibai skill;  
  
}
